package be.winnetrie.mod.simpleserverutilities.network;
import be.winnetrie.mod.simpleserverutilities.SimpleServerUtilities;import net.minecraft.network.RegistryFriendlyByteBuf;import net.minecraft.network.codec.StreamCodec;import net.minecraft.network.protocol.common.custom.CustomPacketPayload;import net.minecraft.resources.Identifier;
public record MineActionPayload(String action,String mineId,String json,long requestId) implements CustomPacketPayload{public static final Type<MineActionPayload> TYPE=new Type<>(Identifier.fromNamespaceAndPath(SimpleServerUtilities.MODID,"mine_action"));public static final StreamCodec<RegistryFriendlyByteBuf,MineActionPayload> STREAM_CODEC=StreamCodec.of(MineActionPayload::encode,MineActionPayload::decode);public MineActionPayload{action=PayloadBounds.string(action,40);mineId=PayloadBounds.string(mineId,64);json=PayloadBounds.string(json,32767);requestId=Math.max(0L,requestId);}private static void encode(RegistryFriendlyByteBuf b,MineActionPayload p){b.writeUtf(p.action,40);b.writeUtf(p.mineId,64);b.writeUtf(p.json,32767);b.writeVarLong(p.requestId);}private static MineActionPayload decode(RegistryFriendlyByteBuf b){return new MineActionPayload(b.readUtf(40),b.readUtf(64),b.readUtf(32767),b.readVarLong());}@Override public Type<? extends CustomPacketPayload> type(){return TYPE;}}
